  Ltac trc MU WM H :=
    lazymatch type of H with rw_cells ?segs ?m ?A ?cs =>
      lazymatch type of MU with munch ?W m ?m' =>
        let H' := fresh "T" in
        assert (H' : rw_cells segs m' A cs)
          by (apply (rw_cells_transport segs W m m' A cs H MU WM); cbn [disjoint_from cells_size csize]; lia);
        clear H; rename H' into H
      end
    end.

  (* [comment removed for export] *)
  Lemma z4s1_rebuild : forall mm0 mm (w40 w168 w176 w184 w192 w200 w208 w216 w224 w232 w240 w248 w256 w264 w272 w280 w288 w296
                                       w304 w312 : word) (j0 j1 : list byte) (c b p s l : word) (jp : list byte)
                                (x272 x280 x288 x296 x304 x320 x336 : word),
    Z4SF' mm0 (SPA w40 w168 w176 w184 w192 w200 w208 w216 w224 w232 w240 w248 w256 w264 w272 w280 w288 w296 w304 w312 j0 j1)
          (BD4A c b jp p s l) ->
    munch Wtot mm0 mm -> wmono asegs mm0 mm -> mem_inv asegs mm ->
    (exists buf, u8arr asegs mm DST (map (Z_to_bv 8) buf) /\ zlen buf = dcap) ->
    rw_cells asegs mm (SP + -576 + 272) [C8 x272] -> rw_cells asegs mm (SP + -576 + 280) [C8 x280] ->
    rw_cells asegs mm (SP + -576 + 288) [C8 x288] -> rw_cells asegs mm (SP + -576 + 296) [C8 x296] ->
    rw_cells asegs mm (SP + -576 + 304) [C8 x304] -> rw_cells asegs mm (SP + -576 + 320) [C8 x320] ->
    rw_cells asegs mm (SP + -576 + 336) [C8 x336] -> 6 <= dcap ->
    Z4SF' mm (SPA w40 w168 w176 w184 w192 w200 w208 w216 w224 w232 w240 w248 w256 w264 x272 x280 x288 x296 x304 w312 j0 j1)
